    public sealed class VisualValidationReport
    {
        public readonly List<string> Errors=new List<string>();public readonly List<string> Warnings=new List<string>();public bool IsValid=>Errors.Count==0;
    }

    public static class VisualProjectValidator
    {
        public static VisualValidationReport ValidateAll()
        {
            var report=new VisualValidationReport();var catalog=AssetDatabase.LoadAssetAtPath<VisualCatalogAsset>(VisualProofAssetGenerator.CatalogPath);if(catalog==null){report.Errors.Add("Visual catalog is missing.");return report;}VisualCatalog core;try{core=catalog.BuildCoreCatalog();var validation=core.Validate();report.Errors.AddRange(validation.Errors);report.Warnings.AddRange(validation.Warnings);}catch(Exception ex){report.Errors.Add("Catalog construction failed: "+ex.Message);return report;}var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var entry in catalog.Assets){if(!seen.Add(entry.id))report.Errors.Add("Duplicate visual asset ID: "+entry.id);if(!ValidName(entry.id))report.Errors.Add("Invalid machine name: "+entry.id);if(entry.prefab==null){report.Errors.Add("Missing prefab: "+entry.id);continue;}var lod=entry.prefab.GetComponent<LODGroup>();if(lod==null||lod.GetLODs().Length<3)report.Errors.Add("Missing three-tier LOD: "+entry.id);var renderers=entry.prefab.GetComponentsInChildren<Renderer>(true);if(renderers.Length==0)report.Errors.Add("Missing renderer: "+entry.id);if(renderers.Any(x=>x.sharedMaterials.Any(m=>m==null)))report.Errors.Add("Missing material: "+entry.id);if(renderers.Length>6)report.Warnings.Add("Near renderer budget exceeded: "+entry.id);var materials=new HashSet<Material>();foreach(var renderer in renderers)foreach(var material in renderer.sharedMaterials)if(material!=null)materials.Add(material);if(materials.Count>4)report.Warnings.Add("Near material budget exceeded: "+entry.id);if(entry.category==VisualAssetCategory.Body||entry.category==VisualAssetCategory.ConsolidatedCharacter)ValidateHumanRig(entry.prefab,report);if(entry.category==VisualAssetCategory.Mount)ValidateMountRig(entry.prefab,report);}
            var animation=AssetDatabase.LoadAssetAtPath<AnimationSetAsset>(VisualProofAssetGenerator.AnimationSetPath);if(animation==null||animation.controller==null)report.Errors.Add("Shared animation set/controller is missing.");else{var required=new[]{"Idle","Walk","Run","Turn","OneHandedAttack","Thrust","PolearmAction","FirearmAim","FirearmFire","FirearmReload","HitReaction","Death","MountedIdle","MountedLocomotion","MountedAttack"};foreach(var name in required)if(!animation.clips.Any(x=>x!=null&&StringComparer.Ordinal.Equals(x.name,"ANM_"+name)))report.Errors.Add("Missing proof animation: "+name);}
            foreach(var file in new[]{"BODY_Human_Proof.json","WPN_Sword_Proof.json","MNT_Horse_Proof.json"})if(!File.Exists(Path.GetFullPath(VisualProofAssetGenerator.Root+"/Specs/"+file)))report.Errors.Add("Machine-readable asset spec is missing: "+file);return report;
        }
        private static void ValidateHumanRig(GameObject prefab,VisualValidationReport report){var root=prefab.GetComponentsInChildren<Transform>(true).FirstOrDefault(x=>x.name=="Root");var bones=root==null?Array.Empty<string>():root.GetComponentsInChildren<Transform>(true).Select(x=>x.name).ToArray();var sockets=bones.Where(x=>x.StartsWith("Socket_",StringComparison.Ordinal)).ToArray();var skin=prefab.GetComponentInChildren<SkinnedMeshRenderer>(true);var descriptor=new RigDescriptor(RigKind.Humanoid,bones,sockets,skin!=null&&skin.sharedMesh!=null&&skin.sharedMesh.bindposes.Length>0,skin==null||skin.sharedMesh==null?0:MaximumInfluences(skin.sharedMesh),prefab.transform.localScale==Vector3.one?"meters-1.0":"invalid-scale",prefab.transform.localRotation==Quaternion.identity?"+Z":"invalid-forward");foreach(var error in RigValidator.Validate(descriptor).Errors)report.Errors.Add(prefab.name+": "+error);var animator=prefab.GetComponent<Animator>();if(animator==null||animator.cullingMode!=AnimatorCullingMode.CullUpdateTransforms)report.Errors.Add(prefab.name+": Animator culling is not configured.");if(animator==null||animator.avatar==null||!animator.avatar.isValid||!animator.avatar.isHuman)report.Errors.Add(prefab.name+": Humanoid Avatar is missing or invalid.");}
        private static void ValidateMountRig(GameObject prefab,VisualValidationReport report){var root=prefab.GetComponentsInChildren<Transform>(true).FirstOrDefault(x=>x.name=="MountRoot");var names=root==null?Array.Empty<string>():root.GetComponentsInChildren<Transform>(true).Select(x=>x.name).ToArray();var skin=prefab.GetComponentInChildren<SkinnedMeshRenderer>(true);var descriptor=new RigDescriptor(RigKind.GenericMount,names,names.Where(x=>x.StartsWith("Socket_",StringComparison.Ordinal)),skin!=null&&skin.sharedMesh!=null&&skin.sharedMesh.bindposes.Length>0,skin==null||skin.sharedMesh==null?0:MaximumInfluences(skin.sharedMesh),prefab.transform.localScale==Vector3.one?"meters-1.0":"invalid-scale",prefab.transform.localRotation==Quaternion.identity?"+Z":"invalid-forward");foreach(var error in RigValidator.Validate(descriptor).Errors)report.Errors.Add(prefab.name+": "+error);}
        private static int MaximumInfluences(Mesh mesh){var max=0;foreach(var w in mesh.boneWeights){var n=(w.weight0>0?1:0)+(w.weight1>0?1:0)+(w.weight2>0?1:0)+(w.weight3>0?1:0);if(n>max)max=n;}return max;}private static bool ValidName(string value){if(string.IsNullOrWhiteSpace(value)||!value.EndsWith("_Proof",StringComparison.Ordinal))return false;foreach(var c in value)if(!(char.IsLetterOrDigit(c)||c=='_'))return false;return true;}
    }

    public static class VisualSmokeRunner
    {
        public static IReadOnlyList<string> Run()
        {
            var catalog=AssetDatabase.LoadAssetAtPath<VisualCatalogAsset>(VisualProofAssetGenerator.CatalogPath)??throw new InvalidOperationException("Visual catalog is missing.");var messages=new List<string>();foreach(var kind in new[]{"deli","humbaraci","bostanci"}){var fixture=Create(kind);var host=new GameObject("Smoke_"+kind);try{var view=host.AddComponent<VisualSoldier3D>();var assembler=host.AddComponent<VisualSoldier3DAssembler>();assembler.Configure(catalog);var before=fixture.soldier.Loadout;var first=assembler.Assemble(view,fixture.soldier,fixture.troop,fixture.equipment);var firstSignature=first.Signature;var second=assembler.Assemble(view,fixture.soldier,fixture.troop,fixture.equipment);if(!firstSignature.Equals(second.Signature))throw new InvalidOperationException(kind+" visual signature changed across assembly.");if(!ReferenceEquals(before,fixture.soldier.Loadout))throw new InvalidOperationException(kind+" gameplay loadout was mutated.");if(!view.Binding.IsBound||!view.Binding.SoldierId!.Value.Equals(fixture.soldier.Id))throw new InvalidOperationException(kind+" binding failed.");if(kind=="deli"&&!second.Modules.Any(x=>x.Category==VisualAssetCategory.Mount))throw new InvalidOperationException("Deli mount visual did not resolve.");if(kind=="humbaraci"&&!second.Modules.Any(x=>x.AssetId.Value=="AUX_Humbara_Proof"))throw new InvalidOperationException("Humbaraci auxiliary visual did not resolve.");if(kind=="bostanci"&&!second.Modules.Any(x=>x.Category==VisualAssetCategory.BodyArmor))throw new InvalidOperationException("Bostanci armor visual did not resolve.");var materials=view.GetComponentsInChildren<Renderer>(true).SelectMany(x=>x.sharedMaterials).Where(x=>x!=null).Distinct().Count();if(materials>6)throw new InvalidOperationException(kind+" material budget exploded.");messages.Add(kind+":PASS signature="+second.Signature.Value+" modules="+second.Modules.Count+" sharedMaterials="+materials);}finally{UnityEngine.Object.DestroyImmediate(host);}}return messages;
        }
        private static (SoldierInstance soldier,TroopDefinition troop,Dictionary<EquipmentInstanceId,EquipmentInstance> equipment) Create(string kind){var sid=SoldierId.Create("proof-"+kind);var weapons=new List<WeaponSlotAssignment>();var armor=new List<ArmorSlotAssignment>();EquipmentInstanceId? shield=null;EquipmentInstanceId? mount=null;var equipment=new Dictionary<EquipmentInstanceId,EquipmentInstance>();void Add(EquipmentInstanceId id,EquipmentDefinitionRef definition){equipment.Add(id,new EquipmentInstance(id,definition,EquipmentOwnerRef.Soldier(sid),EquipmentAcquisitionProvenance.CityMarket(CityId.Create("proof-city"),TradeGoodId.Create("proof-good"),new WorldTimestamp(0))));}if(kind=="deli"){var lance=E("deli-lance");var sword=E("deli-sword");var horse=E("deli-mount");Add(lance,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("lance")));Add(sword,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("sword")));Add(horse,EquipmentDefinitionRef.Mount(MountDefinitionId.Create("fast-mount")));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Main,lance));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Sidearm,sword));mount=horse;}else if(kind=="humbaraci"){var musket=E("hum-musket");var shot=E("hum-shot");var bomb=E("hum-bomb");var side=E("hum-side");Add(musket,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("musket")));Add(shot,EquipmentDefinitionRef.Auxiliary(AuxiliaryEquipmentDefinitionId.Create("shot")));Add(bomb,EquipmentDefinitionRef.Auxiliary(AuxiliaryEquipmentDefinitionId.Create("humbara")));Add(side,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("yatagan")));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Main,musket));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Ammo,shot));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Special,bomb));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Sidearm,side));}else{var pole=E("bost-pole");var pistol=E("bost-pistol");var side=E("bost-side");var body=E("bost-armor");var shd=E("bost-shield");Add(pole,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("polearm")));Add(pistol,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("pistol")));Add(side,EquipmentDefinitionRef.Weapon(WeaponDefinitionId.Create("yatagan")));Add(body,EquipmentDefinitionRef.Armor(ArmorDefinitionId.Create("body-armor")));Add(shd,EquipmentDefinitionRef.Shield(ShieldDefinitionId.Create("shield")));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Main,pole));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Secondary,pistol));weapons.Add(new WeaponSlotAssignment(WeaponSlot.Sidearm,side));armor.Add(new ArmorSlotAssignment(ArmorSlot.Body,body));shield=shd;}var loadout=new SoldierLoadout(weapons,armor,shield,mount);var troop=new TroopDefinition(TroopDefinitionId.Create(kind),kind,UnitClassId.Create("proof-class"),CombatRoleId.Create("proof-role"),kind=="deli"?MountContext.MountedOnly:MountContext.InfantryOnly,VisualProfileId.Create(kind));var soldier=new SoldierInstance(sid,UnitGroupId.Create("proof-unit"),troop.Id,new SoldierRecruitmentProvenance(RecruitmentSourceId.Create("proof-source"),RecruitmentRecordId.Create("proof-record")),loadout,CombatRoleId.Create("proof-role"));return(soldier,troop,equipment);}private static EquipmentInstanceId E(string value)=>EquipmentInstanceId.Create(value);
    }

    [Serializable]public sealed class VisualBenchmarkReport{public string unityVersion=string.Empty;public string operatingSystem=string.Empty;public string processor=string.Empty;public int processorCount;public int systemMemoryMb;public string graphicsDevice=string.Empty;public string graphicsApi=string.Empty;public bool graphicsAvailable;public string renderPipeline="Built-in";public string resolution="batchmode-nographics";public string warmup="10 prefab instantiations";public List<VisualBenchmarkMeasurement> measurements=new List<VisualBenchmarkMeasurement>();public string gpuTiming="unavailable in -nographics batchmode";public string renderThreadTiming="unavailable in -nographics batchmode";public string frameTiming="unavailable: editor batch assembly benchmark, not a playable battle frame";}
    [Serializable]public sealed class VisualBenchmarkMeasurement{public string scenario=string.Empty;public string strategy=string.Empty;public int actorCount;public double spawnMilliseconds;public long managedMemoryDeltaBytes;public int rendererCount;public int sharedMaterialCount;}

    public static class VisualBenchmarkRunner
    {
        public static VisualBenchmarkReport Run()
        {
            var report=new VisualBenchmarkReport{unityVersion=Application.unityVersion,operatingSystem=SystemInfo.operatingSystem,processor=SystemInfo.processorType,processorCount=SystemInfo.processorCount,systemMemoryMb=SystemInfo.systemMemorySize,graphicsDevice=SystemInfo.graphicsDeviceName,graphicsApi=SystemInfo.graphicsDeviceType.ToString(),graphicsAvailable=SystemInfo.graphicsDeviceType!=UnityEngine.Rendering.GraphicsDeviceType.Null};GameObject P(string id)=>AssetDatabase.LoadAssetAtPath<GameObject>(VisualProofAssetGenerator.Root+"/Prefabs/"+id+".prefab")??throw new InvalidOperationException("Benchmark proof prefab is missing: "+id);var body=P("BODY_Human_Proof");var head=P("HEAD_A_Proof");var clothing=P("CLTH_Light_Proof");var armor=P("ARM_Guard_Proof");var headgear=P("HDG_Guard_Proof");var sword=P("WPN_Sword_Proof");var mount=P("MNT_Horse_Proof");var consolidated=P("CHR_Consolidated_Proof");var far=P("CRWD_Far_Proof");var modular=new[]{body,head,clothing,sword};var consolidatedSet=new[]{consolidated,sword};Warm(consolidated);foreach(var count in new[]{1,50,100,250,500})report.measurements.Add(Measure("identical-infantry","cached-consolidated",consolidatedSet,count));report.measurements.Add(Measure("varied-infantry","modular",modular,100));report.measurements.Add(Measure("infantry-cavalry","cached-consolidated",new[]{consolidated,sword,mount},100));report.measurements.Add(Measure("named-subset","modular-high-detail",new[]{body,head,armor,headgear,sword},100));report.measurements.Add(Measure("far-crowd","lod2-representation",new[]{far},100));report.measurements.Add(Measure("architecture-comparison","modular",modular,100));report.measurements.Add(Measure("architecture-comparison","cached-consolidated",consolidatedSet,100));report.measurements.Add(Measure("architecture-comparison","lod2-representation",new[]{far},100));Write(report);return report;
        }
        private static void Warm(GameObject prefab){for(var i=0;i<10;i++){var x=UnityEngine.Object.Instantiate(prefab);UnityEngine.Object.DestroyImmediate(x);}}
        private static VisualBenchmarkMeasurement Measure(string scenario,string strategy,IReadOnlyList<GameObject> prefabs,int count){GC.Collect();var before=GC.GetTotalMemory(true);var roots=new GameObject[count];var watch=Stopwatch.StartNew();for(var i=0;i<count;i++){var root=new GameObject("BenchmarkActor");roots[i]=root;foreach(var prefab in prefabs)UnityEngine.Object.Instantiate(prefab,root.transform,false);}watch.Stop();var after=GC.GetTotalMemory(false);var rendererPer=prefabs.Sum(x=>x.GetComponentsInChildren<Renderer>(true).Length);var materials=new HashSet<Material>();foreach(var prefab in prefabs)foreach(var renderer in prefab.GetComponentsInChildren<Renderer>(true))foreach(var material in renderer.sharedMaterials)if(material!=null)materials.Add(material);for(var i=roots.Length-1;i>=0;i--)UnityEngine.Object.DestroyImmediate(roots[i]);return new VisualBenchmarkMeasurement{scenario=scenario,strategy=strategy,actorCount=count,spawnMilliseconds=Math.Round(watch.Elapsed.TotalMilliseconds,3),managedMemoryDeltaBytes=Math.Max(0,after-before),rendererCount=rendererPer*count,sharedMaterialCount=materials.Count};}
        private static void Write(VisualBenchmarkReport report){var directory=Path.GetFullPath(Path.Combine(Application.dataPath,"..","..","TestResults"));Directory.CreateDirectory(directory);File.WriteAllText(Path.Combine(directory,"visual-benchmark.json"),JsonUtility.ToJson(report,true));}
    }
}
